    fun setUp() {
        connectUserDatabaseUtilMock = Mockito.mockStatic(ConnectUserDatabaseUtil::class.java)
        user =
            ConnectUserRecord(
                "+11234567890",
                "test-user-id",
                "test-password",
                "Ada Lovelace",
                "",
                null,
                null,
                false,
                "",
